WITH Flagged AS (SELECT customer_id, transaction_date, amount, LAG(transaction_date, 1) OVER (PARTITION BY customer_id ORDER BY transaction_date) AS prev_date, LAG(amount, 1) OVER (PARTITION BY customer_id ORDER BY transaction_date) AS prev_amount FROM Transactions), Graded AS (SELECT customer_id, transaction_date, amount, SUM(CASE WHEN prev_date IS NULL OR DATEDIFF(transaction_date, prev_date) > 1 OR amount <= prev_amount THEN 1 ELSE 0 END) OVER (PARTITION BY customer_id ORDER BY transaction_date) AS streak_id FROM Flagged) SELECT customer_id, MIN(transaction_date) AS consecutive_start, MAX(transaction_date) AS consecutive_end FROM Graded GROUP BY customer_id, streak_id HAVING COUNT(*) >= 3 ORDER BY customer_id ASC, consecutive_start ASC, consecutive_end ASC;
